{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://navia.local/contracts/v2_px_derived_facts.schema.json",
  "title": "Navia V2 PX Derived Facts v1",
  "type": "object",
  "additionalProperties": false,
  "required": ["schemaVersion", "evidenceClass", "runId", "generatedAt", "sealedRawRun", "generatorImplementation", "sourceMappings", "scenarioFacts", "summary", "seal"],
  "properties": {
    "schemaVersion": {"const": "v2-px-derived-facts/v1"},
    "evidenceClass": {"const": "production_acceptance"},
    "runId": {"type": "string", "minLength": 1},
    "generatedAt": {"type": "string", "format": "date-time"},
    "sealedRawRun": {"$ref": "#/$defs/ArtifactRef"},
    "generatorImplementation": {"$ref": "#/$defs/ArtifactRef"},
    "sourceMappings": {"type": "array", "minItems": 12, "items": {"$ref": "#/$defs/SourceMapping"}},
    "scenarioFacts": {"type": "array", "minItems": 1, "items": {"$ref": "#/$defs/ScenarioFact"}},
    "summary": {"type": "object", "minProperties": 1},
    "seal": {"$ref": "#/$defs/Seal"}
  },
  "$defs": {
    "ArtifactRef": {
      "type": "object", "additionalProperties": false,
      "required": ["artifactRoot", "path", "sha256", "byteLength", "mediaType"],
      "properties": {
        "artifactRoot": {"enum": ["source_run", "validation_run", "repository_snapshot"]},
        "path": {"type": "string", "minLength": 1, "pattern": "^(?!/)(?![A-Za-z]:)(?!.*(?:^|/)\\.\\.(?:/|$))(?!virtual/)[^\\u0000]+$"},
        "sha256": {"type": "string", "pattern": "^[a-f0-9]{64}$"},
        "byteLength": {"type": "integer", "minimum": 0},
        "mediaType": {"type": "string", "minLength": 1}
      }
    },
    "SourceMapping": {
      "type": "object", "additionalProperties": false,
      "required": ["sourceSampleId", "sourceId", "workspaceId", "sourceType", "contentFingerprint", "registrationArtifactRef", "importRequestEventId", "importResponseEventId"],
      "properties": {
        "sourceSampleId": {"type": "string", "minLength": 1}, "sourceId": {"type": "string", "minLength": 1},
        "workspaceId": {"type": "string", "minLength": 1}, "sourceType": {"enum": ["web", "local", "note"]},
        "contentFingerprint": {"type": "string", "pattern": "^sha256:[a-f0-9]{64}$"},
        "registrationArtifactRef": {"$ref": "#/$defs/ArtifactRef"},
        "importRequestEventId": {"type": "string", "minLength": 1}, "importResponseEventId": {"type": "string", "minLength": 1},
        "operationId": {"type": "string", "minLength": 1}
      }
    },
    "Provenance": {
      "type": "object", "additionalProperties": false,
      "required": ["domActionEventIds", "backgroundRequestEventIds", "backgroundResponseEventIds", "runtimeRequestEventIds", "runtimeTerminalEventIds", "routeObservationEventIds", "containerObservationEventIds", "screenshotEventIds", "commandResultEventIds", "faultEventIds"],
      "properties": {
        "domActionEventIds": {"$ref": "#/$defs/Ids"}, "backgroundRequestEventIds": {"$ref": "#/$defs/Ids"},
        "backgroundResponseEventIds": {"$ref": "#/$defs/Ids"}, "runtimeRequestEventIds": {"$ref": "#/$defs/Ids"},
        "runtimeTerminalEventIds": {"$ref": "#/$defs/Ids"}, "routeObservationEventIds": {"$ref": "#/$defs/Ids"},
        "containerObservationEventIds": {"$ref": "#/$defs/Ids"}, "screenshotEventIds": {"$ref": "#/$defs/Ids"},
        "commandResultEventIds": {"$ref": "#/$defs/Ids"}, "faultEventIds": {"$ref": "#/$defs/Ids"}
      }
    },
    "Ids": {"type": "array", "uniqueItems": true, "items": {"type": "string", "minLength": 1}},
    "ScenarioFact": {
      "type": "object", "additionalProperties": false,
      "required": ["scenarioId", "passed", "provenance", "facts"],
      "properties": {"scenarioId": {"type": "string", "minLength": 1}, "passed": {"type": "boolean"}, "provenance": {"$ref": "#/$defs/Provenance"}, "facts": {"type": "object"}}
    },
    "Seal": {
      "type": "object", "additionalProperties": false,
      "required": ["inputMode", "contentSha256"],
      "properties": {"inputMode": {"const": "canonical_json_without_seal_v1"}, "contentSha256": {"type": "string", "pattern": "^[a-f0-9]{64}$"}}
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://navia.local/contracts/v2_px_production_validation.schema.json",
  "title": "Navia V2 PX Production Validation v1",
  "type": "object", "additionalProperties": false,
  "required": ["schemaVersion", "profile", "validationRunId", "sourceRunId", "validatedAt", "inputs", "ruleResults", "gateResults", "contractRegression", "productionMutationResults", "machinePassed", "humanReviewStatus", "finalPassed", "issues"],
  "properties": {
    "schemaVersion": {"const": "v2-px-production-validation/v1"},
    "profile": {"enum": ["contract_fixture", "production_candidate", "production_final"]},
    "validationRunId": {"type": "string", "minLength": 1}, "sourceRunId": {"type": "string", "minLength": 1},
    "validatedAt": {"type": "string", "format": "date-time"},
    "inputs": {"type": "object", "additionalProperties": false, "required": ["raw", "derived", "validator", "semanticSpec", "registry", "fixtureSuite"], "properties": {"raw": {"$ref": "#/$defs/ArtifactRef"}, "derived": {"$ref": "#/$defs/ArtifactRef"}, "validator": {"$ref": "#/$defs/ArtifactRef"}, "semanticSpec": {"$ref": "#/$defs/ArtifactRef"}, "registry": {"$ref": "#/$defs/ArtifactRef"}, "fixtureSuite": {"$ref": "#/$defs/ArtifactRef"}}},
    "ruleResults": {"type": "array", "minItems": 63, "maxItems": 63, "items": {"$ref": "#/$defs/RuleResult"}},
    "gateResults": {"type": "object", "additionalProperties": false, "required": ["G1", "G2", "G3", "G4", "G5", "G6", "G7"], "properties": {"G1": {"$ref": "#/$defs/Status"}, "G2": {"$ref": "#/$defs/Status"}, "G3": {"$ref": "#/$defs/Status"}, "G4": {"$ref": "#/$defs/Status"}, "G5": {"$ref": "#/$defs/Status"}, "G6": {"$ref": "#/$defs/Status"}, "G7": {"$ref": "#/$defs/Status"}}},
    "contractRegression": {"$ref": "#/$defs/SuiteResult"}, "productionMutationResults": {"$ref": "#/$defs/SuiteResult"},
    "machinePassed": {"type": "boolean"}, "humanReviewStatus": {"enum": ["pending", "passed", "failed"]}, "finalPassed": {"type": "boolean"},
    "issues": {"type": "array", "items": {"type": "string", "minLength": 1}}
  },
  "$defs": {
    "ArtifactRef": {"type": "object", "additionalProperties": false, "required": ["artifactRoot", "path", "sha256", "byteLength", "mediaType"], "properties": {"artifactRoot": {"enum": ["source_run", "validation_run", "repository_snapshot"]}, "path": {"type": "string", "minLength": 1, "pattern": "^(?!/)(?![A-Za-z]:)(?!.*(?:^|/)\\.\\.(?:/|$))(?!virtual/)[^\\u0000]+$"}, "sha256": {"type": "string", "pattern": "^[a-f0-9]{64}$"}, "byteLength": {"type": "integer", "minimum": 0}, "mediaType": {"type": "string", "minLength": 1}}},
    "Status": {"enum": ["passed", "failed", "pending"]},
    "RuleResult": {"type": "object", "additionalProperties": false, "required": ["ruleId", "enforcementLayer", "status", "failureCode", "evidenceRefs", "notes"], "properties": {"ruleId": {"type": "string", "pattern": "^PX_RULE_[A-Z0-9_]+$"}, "enforcementLayer": {"enum": ["schema", "semantic"]}, "status": {"enum": ["passed", "failed", "pending", "not_applicable"]}, "failureCode": {"type": ["string", "null"], "pattern": "^(?:SCHEMA_VALIDATION_FAILED|PX_[A-Z0-9_]+)$"}, "evidenceRefs": {"type": "array", "items": {"$ref": "#/$defs/ArtifactRef"}}, "notes": {"type": "string"}}},
    "SuiteResult": {"type": "object", "additionalProperties": false, "required": ["suiteId", "total", "passed", "failed", "resultArtifact"], "properties": {"suiteId": {"type": "string", "minLength": 1}, "total": {"type": "integer", "minimum": 1}, "passed": {"type": "integer", "minimum": 0}, "failed": {"type": "integer", "minimum": 0}, "resultArtifact": {"$ref": "#/$defs/ArtifactRef"}}}
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://navia.local/contracts/v2_px_collection_diagnostic.schema.json",
  "title": "Navia V2 PX Collection Diagnostic v1",
  "type": "object", "additionalProperties": false,
  "required": ["schemaVersion", "runId", "sourceRawRun", "generatedAt", "passed", "missingObservations", "issues", "generatorImplementation"],
  "properties": {
    "schemaVersion": {"const": "v2-px-collection-diagnostic/v1"}, "runId": {"type": "string", "minLength": 1}, "sourceRawRun": {"$ref": "#/$defs/ArtifactRef"}, "generatedAt": {"type": "string", "format": "date-time"}, "passed": {"const": false},
    "missingObservations": {"type": "array", "minItems": 1, "items": {"type": "object", "additionalProperties": false, "required": ["requirementId", "numerator", "denominator", "observed", "required", "eventKinds", "scenarioIds"], "properties": {"requirementId": {"type": "string", "minLength": 1}, "numerator": {"type": "string", "minLength": 1}, "denominator": {"type": "string", "minLength": 1}, "observed": {"type": "integer", "minimum": 0}, "required": {"type": "integer", "minimum": 1}, "eventKinds": {"type": "array", "items": {"type": "string"}}, "scenarioIds": {"type": "array", "items": {"type": "string"}}}}},
    "issues": {"type": "array", "minItems": 1, "items": {"type": "string", "minLength": 1}}, "generatorImplementation": {"$ref": "#/$defs/ArtifactRef"}
  },
  "$defs": {"ArtifactRef": {"type": "object", "additionalProperties": false, "required": ["artifactRoot", "path", "sha256", "byteLength", "mediaType"], "properties": {"artifactRoot": {"enum": ["source_run", "validation_run", "repository_snapshot"]}, "path": {"type": "string", "minLength": 1, "pattern": "^(?!/)(?![A-Za-z]:)(?!.*(?:^|/)\\.\\.(?:/|$))(?!virtual/)[^\\u0000]+$"}, "sha256": {"type": "string", "pattern": "^[a-f0-9]{64}$"}, "byteLength": {"type": "integer", "minimum": 0}, "mediaType": {"type": "string", "minLength": 1}}}}
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://navia.local/contracts/v2_px_production_package.schema.json",
  "title": "Navia V2 PX Production Package v1",
  "type": "object", "additionalProperties": false,
  "required": ["schemaVersion", "evidenceClass", "acceptanceProfile", "runId", "createdAt", "sealedRawRun", "derivedFacts", "productionValidation", "contractRegression", "humanReview", "renderedReport", "acceptanceHtml", "automatedCandidatePassed", "humanReviewStatus", "passed", "claim"],
  "properties": {
    "schemaVersion": {"const": "v2-px-production-package/v1"}, "evidenceClass": {"const": "production_acceptance"},
    "acceptanceProfile": {"enum": ["production_candidate", "production_final"]}, "runId": {"type": "string", "minLength": 1}, "createdAt": {"type": "string", "format": "date-time"},
    "sealedRawRun": {"$ref": "#/$defs/ArtifactRef"}, "derivedFacts": {"$ref": "#/$defs/ArtifactRef"}, "productionValidation": {"$ref": "#/$defs/ArtifactRef"}, "contractRegression": {"$ref": "#/$defs/ArtifactRef"}, "humanReview": {"$ref": "#/$defs/ArtifactRef"}, "renderedReport": {"$ref": "#/$defs/ArtifactRef"}, "acceptanceHtml": {"$ref": "#/$defs/ArtifactRef"},
    "automatedCandidatePassed": {"type": "boolean"}, "humanReviewStatus": {"enum": ["pending", "passed", "failed"]}, "passed": {"type": "boolean"}, "claim": {"type": "string", "minLength": 1}
  },
  "$defs": {"ArtifactRef": {"type": "object", "additionalProperties": false, "required": ["artifactRoot", "path", "sha256", "byteLength", "mediaType"], "properties": {"artifactRoot": {"enum": ["source_run", "validation_run", "repository_snapshot"]}, "path": {"type": "string", "minLength": 1, "pattern": "^(?!/)(?![A-Za-z]:)(?!.*(?:^|/)\\.\\.(?:/|$))(?!virtual/)[^\\u0000]+$"}, "sha256": {"type": "string", "pattern": "^[a-f0-9]{64}$"}, "byteLength": {"type": "integer", "minimum": 0}, "mediaType": {"type": "string", "minLength": 1}}}}
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://navia.local/contracts/v2_px_invocation_record.schema.json",
  "title": "Navia V2 PX Invocation Record v1",
  "type": "object",
  "additionalProperties": false,
  "required": ["schemaVersion", "evidenceClass", "profile", "validationRunId", "sourceRunId", "recordedAt", "steps", "productionPackage", "exitCode", "passed", "claimBoundary"],
  "properties": {
    "schemaVersion": {"const": "v2-px-invocation-record/v1"},
    "evidenceClass": {"const": "production_acceptance"},
    "profile": {"const": "production_candidate"},
    "validationRunId": {"type": "string", "minLength": 1},
    "sourceRunId": {"type": "string", "minLength": 1},
    "recordedAt": {"type": "string", "format": "date-time"},
    "steps": {
      "type": "array",
      "minItems": 4,
      "maxItems": 4,
      "items": {"$ref": "#/$defs/InvocationStep"},
      "allOf": [
        {"contains": {"properties": {"stepId": {"const": "derive"}}, "required": ["stepId"]}, "minContains": 1, "maxContains": 1},
        {"contains": {"properties": {"stepId": {"const": "validate"}}, "required": ["stepId"]}, "minContains": 1, "maxContains": 1},
        {"contains": {"properties": {"stepId": {"const": "report"}}, "required": ["stepId"]}, "minContains": 1, "maxContains": 1},
        {"contains": {"properties": {"stepId": {"const": "package"}}, "required": ["stepId"]}, "minContains": 1, "maxContains": 1}
      ]
    },
    "productionPackage": {"$ref": "#/$defs/ArtifactRef"},
    "exitCode": {"const": 0},
    "passed": {"const": true},
    "claimBoundary": {"type": "string", "minLength": 1}
  },
  "$defs": {
    "ArtifactRef": {
      "type": "object",
      "additionalProperties": false,
      "required": ["artifactRoot", "path", "sha256", "byteLength", "mediaType"],
      "properties": {
        "artifactRoot": {"enum": ["source_run", "validation_run", "repository_snapshot"]},
        "path": {"type": "string", "minLength": 1, "pattern": "^(?!/)(?![A-Za-z]:)(?!.*(?:^|/)\\.\\.(?:/|$))(?!virtual/)[^\\u0000]+$"},
        "sha256": {"type": "string", "pattern": "^[a-f0-9]{64}$"},
        "byteLength": {"type": "integer", "minimum": 0},
        "mediaType": {"type": "string", "minLength": 1}
      }
    },
    "InvocationStep": {
      "type": "object",
      "additionalProperties": false,
      "required": ["stepId", "implementation", "cwdRole", "argv", "exitCode", "signal", "stdout", "stderr"],
      "properties": {
        "stepId": {"enum": ["derive", "validate", "report", "package"]},
        "implementation": {"$ref": "#/$defs/ArtifactRef"},
        "cwdRole": {"enum": ["repository_root", "extension_root", "isolated_temp"]},
        "argv": {"type": "array", "minItems": 1, "items": {"type": "string", "minLength": 1}},
        "exitCode": {"const": 0},
        "signal": {"type": ["string", "null"]},
        "stdout": {"$ref": "#/$defs/ArtifactRef"},
        "stderr": {"$ref": "#/$defs/ArtifactRef"}
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://navia.local/contracts/v2_external_brain_report.schema.json",
  "title": "V2-PX Acceptance Report",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schemaVersion",
    "generatedAt",
    "evidenceClass",
    "acceptanceMode",
    "claim",
    "passed",
    "humanReview",
    "summary",
    "gateResults",
    "scenarioResults",
    "testCommands",
    "auditArtifacts",
    "fatalIssues",
    "majorIssues",
    "warnings"
  ],
  "properties": {
    "schemaVersion": {
      "const": "v2-external-brain-report/v12"
    },
    "generatedAt": {
      "type": "string",
      "format": "date-time"
    },
    "evidenceClass": {
      "enum": [
        "contract_fixture",
        "production_acceptance"
      ]
    },
    "acceptanceMode": {
      "enum": [
        "contract_fixture",
        "real_chrome_dual_container"
      ]
    },
    "claim": {
      "enum": [
        "V2-PX External Brain Productization passed dual-container real-Chrome acceptance.",
        "V2-PX contract fixture satisfied the frozen semantic rules; not product acceptance evidence.",
        "V2-PX External Brain Productization acceptance did not pass."
      ]
    },
    "passed": {
      "type": "boolean"
    },
    "humanReview": {
      "$ref": "#/$defs/HumanReviewRef"
    },
    "summary": {
      "$ref": "#/$defs/Summary"
    },
    "gateResults": {
      "$ref": "#/$defs/GateResults"
    },
    "scenarioResults": {
      "type": "array",
      "minItems": 12,
      "items": {
        "$ref": "#/$defs/ScenarioResult"
      }
    },
    "testCommands": {
      "type": "array",
      "minItems": 1,
      "items": {
        "$ref": "#/$defs/TestCommand"
      }
    },
    "auditArtifacts": {
      "$ref": "#/$defs/AuditArtifacts"
    },
    "fatalIssues": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "majorIssues": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "warnings": {
      "type": "array",
      "items": {
        "type": "string"
      }
    }
  },
  "allOf": [
    {
      "if": {
        "properties": {
          "evidenceClass": {
            "const": "contract_fixture"
          }
        },
        "required": [
          "evidenceClass"
        ]
      },
      "then": {
        "properties": {
          "humanReview": {
            "properties": {
              "evidenceClass": {
                "const": "contract_fixture"
              }
            }
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "evidenceClass": {
            "const": "production_acceptance"
          }
        },
        "required": [
          "evidenceClass"
        ]
      },
      "then": {
        "properties": {
          "humanReview": {
            "properties": {
              "evidenceClass": {
                "const": "production_acceptance"
              }
            }
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "evidenceClass": {
            "const": "contract_fixture"
          }
        },
        "required": [
          "evidenceClass"
        ]
      },
      "then": {
        "properties": {
          "acceptanceMode": {
            "const": "contract_fixture"
          },
          "claim": {
            "const": "V2-PX contract fixture satisfied the frozen semantic rules; not product acceptance evidence."
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "evidenceClass": {
            "const": "production_acceptance"
          }
        },
        "required": [
          "evidenceClass"
        ]
      },
      "then": {
        "properties": {
          "acceptanceMode": {
            "const": "real_chrome_dual_container"
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "passed": {
            "const": true
          }
        },
        "required": [
          "passed"
        ]
      },
      "then": {
        "properties": {
          "claim": {
            "enum": [
              "V2-PX External Brain Productization passed dual-container real-Chrome acceptance.",
              "V2-PX contract fixture satisfied the frozen semantic rules; not product acceptance evidence."
            ]
          },
          "humanReview": {
            "allOf": [
              {
                "$ref": "#/$defs/HumanReviewRef"
              },
              {
                "properties": {
                  "status": {
                    "const": "passed"
                  }
                }
              }
            ]
          },
          "fatalIssues": {
            "maxItems": 0
          },
          "majorIssues": {
            "maxItems": 0
          },
          "gateResults": {
            "$ref": "#/$defs/PassedGateResults"
          },
          "scenarioResults": {
            "items": {
              "allOf": [
                {
                  "$ref": "#/$defs/ScenarioResult"
                },
                {
                  "properties": {
                    "passed": {
                      "const": true
                    }
                  }
                }
              ]
            }
          },
          "testCommands": {
            "items": {
              "allOf": [
                {
                  "$ref": "#/$defs/TestCommand"
                },
                {
                  "properties": {
                    "passed": {
                      "const": true
                    }
                  }
                }
              ]
            }
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "passed": {
            "const": false
          }
        },
        "required": [
          "passed"
        ]
      },
      "then": {
        "properties": {
          "claim": {
            "const": "V2-PX External Brain Productization acceptance did not pass."
          }
        }
      }
    }
  ],
  "$defs": {
    "RouteIntent": {
      "enum": [
        "source_detail",
        "source_library",
        "ask",
        "graph",
        "permissions"
      ]
    },
    "WorkspaceErrorCode": {
      "enum": [
        "WORKSPACE_NOT_FOUND",
        "SOURCE_NOT_FOUND",
        "FORBIDDEN",
        "INVALID_ROUTE",
        "RUNTIME_OFFLINE",
        "OPEN_WORKSPACE_FAILED",
        "UNSUPPORTED_HOST_STRATEGY"
      ]
    },
    "Summary": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "sourceCorpusTotal",
        "uniqueRealWebSources",
        "uniqueExplicitLocalDocumentSources",
        "uniqueNoteMarkdownSources",
        "scenariosTotal",
        "scenariosPassed",
        "entryPointsCovered",
        "routesCovered",
        "routeDirectOpenReloadPairs",
        "invalidOrForbiddenRecoverySamples",
        "idConsistencySamples",
        "statusFaultsCovered",
        "permissionSamples",
        "forgetSamples",
        "v2RegressionPassed"
      ],
      "properties": {
        "sourceCorpusTotal": {
          "type": "integer",
          "minimum": 12
        },
        "uniqueRealWebSources": {
          "type": "integer",
          "minimum": 6
        },
        "uniqueExplicitLocalDocumentSources": {
          "type": "integer",
          "minimum": 3
        },
        "uniqueNoteMarkdownSources": {
          "type": "integer",
          "minimum": 3
        },
        "scenariosTotal": {
          "type": "integer",
          "minimum": 12
        },
        "scenariosPassed": {
          "type": "integer",
          "minimum": 0
        },
        "entryPointsCovered": {
          "type": "integer",
          "minimum": 3
        },
        "routesCovered": {
          "type": "integer",
          "minimum": 5
        },
        "routeDirectOpenReloadPairs": {
          "type": "integer",
          "minimum": 5
        },
        "invalidOrForbiddenRecoverySamples": {
          "type": "integer",
          "minimum": 2
        },
        "idConsistencySamples": {
          "type": "integer",
          "minimum": 4
        },
        "statusFaultsCovered": {
          "type": "integer",
          "minimum": 4
        },
        "permissionSamples": {
          "type": "integer",
          "minimum": 3
        },
        "forgetSamples": {
          "type": "integer",
          "minimum": 3
        },
        "v2RegressionPassed": {
          "type": "boolean"
        }
      }
    },
    "GateResults": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "G1_entry",
        "G2_route",
        "G3_lifecycle",
        "G4_architecture",
        "G5_status",
        "G6_ux_accessibility",
        "G7_evidence"
      ],
      "properties": {
        "G1_entry": {
          "type": "boolean"
        },
        "G2_route": {
          "type": "boolean"
        },
        "G3_lifecycle": {
          "type": "boolean"
        },
        "G4_architecture": {
          "type": "boolean"
        },
        "G5_status": {
          "type": "boolean"
        },
        "G6_ux_accessibility": {
          "type": "boolean"
        },
        "G7_evidence": {
